-- 0002: scan database tables (final state of GOCLER in tarama/depo.py, tarama/portal_depo.py).
-- Existing table names are kept. Times are timestamptz (UTC). Temporary migration tables (firma_yeni, rapor_yeni) are not carried over.
-- Ids are GENERATED BY DEFAULT: like AUTOINCREMENT in SQLite, a deleted id is not reused; the DEFAULT option
-- is so that old ids can be carried over unchanged in the ALIG-DB-004 migration (after migration the counter is advanced with setval).
SET ROLE alig_owner;

CREATE TABLE alig.firma(
  id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  anahtar              text NOT NULL UNIQUE CHECK (anahtar <> ''),
  ad                   text NOT NULL,
  eposta               text NOT NULL,
  durum                text NOT NULL DEFAULT 'aktif' CHECK (durum IN ('aktif', 'pasif')),
  kaynak               text NOT NULL,
  aciklama             text NOT NULL DEFAULT '',
  kayit_utc            timestamptz NOT NULL,
  son_utc              timestamptz NOT NULL,
  dogrudan_izin        boolean NOT NULL DEFAULT false,
  eposta_dogrulama_utc timestamptz
);
CREATE INDEX firma_son ON alig.firma(son_utc);

-- Trace of a deleted company (a digest, not the plain key).
CREATE TABLE alig.firma_silinen(
  anahtar_sha256 text PRIMARY KEY CHECK (anahtar_sha256 ~ '^[0-9a-f]{64}$'),
  silinme_utc    timestamptz NOT NULL
);

-- Report: belge_json stays as TEXT (not jsonb); rationale in db/README.md. When the company is deleted its reports are deleted too.
CREATE TABLE alig.rapor(
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  token_sha256  text NOT NULL UNIQUE CHECK (token_sha256 ~ '^[0-9a-f]{64}$'),
  olusturma_utc timestamptz NOT NULL,
  bitis_utc     timestamptz NOT NULL,
  motor         text NOT NULL,
  dil           text NOT NULL CHECK (dil IN ('tr', 'en')),
  belge_json    text NOT NULL CHECK (belge_json IS JSON OBJECT),
  firma_id      bigint REFERENCES alig.firma(id) ON DELETE CASCADE,
  eposta        text NOT NULL DEFAULT '',
  dogrulandi    boolean NOT NULL DEFAULT true
);
CREATE INDEX rapor_firma ON alig.rapor(firma_id, id);
CREATE INDEX rapor_bitis ON alig.rapor(bitis_utc);

-- Quota: sliding window record. NOT tied to the company by a foreign key (it matches the digest of the company key);
-- when the company is deleted the application deletes the usage rows separately (firma_sil).
CREATE TABLE alig.kullanim(
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  anahtar_sha256 text NOT NULL CHECK (anahtar_sha256 ~ '^[0-9a-f]{64}$'),
  zaman_utc      timestamptz NOT NULL,
  belge_sha256   text CHECK (belge_sha256 ~ '^[0-9a-f]{64}$')
);
CREATE INDEX kullanim_anahtar ON alig.kullanim(anahtar_sha256, zaman_utc);
CREATE INDEX kullanim_belge ON alig.kullanim(anahtar_sha256, belge_sha256, zaman_utc) WHERE belge_sha256 IS NOT NULL;

-- Audit chain (scan). The canonical digest format stays the same as ozet_hesapla in tarama/depo.py; the columns are the same.
-- seq is computed in the application under the last-record lock (not an identity sequence). UNIQUE(onceki) does not let the chain branch.
-- 0005_yetkiler.sql: the application role has only INSERT and SELECT.
CREATE TABLE alig.denetim(
  seq       bigint PRIMARY KEY CHECK (seq >= 1),
  zaman_utc timestamptz NOT NULL,
  aktor     text NOT NULL,
  olay      text NOT NULL,
  onceki    text NOT NULL UNIQUE CHECK (onceki = '' OR onceki ~ '^[0-9a-f]{64}$'),
  ozet      text NOT NULL CHECK (ozet ~ '^[0-9a-f]{64}$'),
  mod       smallint NOT NULL DEFAULT 0 CHECK (mod IN (0, 1, 2, 3)),
  alanlar   text NOT NULL DEFAULT '',
  CHECK (seq > 1 OR onceki = '')
);

-- Mode B (direct connection) request. The login secret is NEVER stored.
CREATE TABLE alig.baglanti_istegi(
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  token_sha256  text NOT NULL UNIQUE CHECK (token_sha256 ~ '^[0-9a-f]{64}$'),
  firma_id      bigint NOT NULL REFERENCES alig.firma(id) ON DELETE CASCADE,
  kanit         text NOT NULL,
  ad            text NOT NULL,
  ip            text NOT NULL,
  port          integer NOT NULL CHECK (port BETWEEN 1 AND 65535),
  veritabani    text NOT NULL,
  kullanici     text NOT NULL,
  maskele       boolean NOT NULL DEFAULT false,
  dil           text NOT NULL CHECK (dil IN ('tr', 'en')),
  olusturma_utc timestamptz NOT NULL,
  bitis_utc     timestamptz NOT NULL,
  deneme        integer NOT NULL DEFAULT 0 CHECK (deneme >= 0),
  durum         text NOT NULL DEFAULT 'bekliyor' CHECK (durum IN ('bekliyor', 'iptal', 'deneme', 'tamam'))
);
CREATE INDEX baglanti_istegi_firma ON alig.baglanti_istegi(firma_id, olusturma_utc);
CREATE INDEX baglanti_istegi_bitis ON alig.baglanti_istegi(bitis_utc);

-- Outbox: emptied once the text is sent.
CREATE TABLE alig.posta(
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  alici         text NOT NULL,
  konu          text NOT NULL,
  metin         text NOT NULL,
  olusturma_utc timestamptz NOT NULL,
  deneme        integer NOT NULL DEFAULT 0 CHECK (deneme >= 0),
  durum         text NOT NULL DEFAULT 'bekliyor' CHECK (durum IN ('bekliyor', 'gonderildi', 'basarisiz')),
  son_hata      text NOT NULL DEFAULT '',
  gonderim_utc  timestamptz
);
CREATE INDEX posta_alici ON alig.posta(alici, olusturma_utc);
CREATE INDEX posta_bekleyen ON alig.posta(id) WHERE durum = 'bekliyor';
CREATE INDEX posta_olusturma ON alig.posta(olusturma_utc);

-- Where the company sync from contact requests left off.
CREATE TABLE alig.esitleme(
  ad    text PRIMARY KEY,
  deger text NOT NULL
);

-- Customer portal (off by default). A verified user has a company; an unverified one may not.
CREATE TABLE alig.portal_kullanici(
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  firma_id      bigint REFERENCES alig.firma(id) ON DELETE CASCADE,
  eposta        text NOT NULL UNIQUE,
  parola        text NOT NULL,
  durum         text NOT NULL DEFAULT 'bekliyor' CHECK (durum IN ('bekliyor', 'aktif')),
  dil           text NOT NULL DEFAULT 'tr' CHECK (dil IN ('tr', 'en')),
  sirket        text NOT NULL DEFAULT '',
  kayit_utc     timestamptz NOT NULL,
  dogrulama_utc timestamptz,
  son_giris_utc timestamptz,
  CHECK (durum = 'bekliyor' OR firma_id IS NOT NULL)
);
CREATE INDEX portal_kullanici_firma ON alig.portal_kullanici(firma_id);

CREATE TABLE alig.portal_kod(
  kod_sha256   text PRIMARY KEY CHECK (kod_sha256 ~ '^[0-9a-f]{64}$'),
  kullanici_id bigint NOT NULL REFERENCES alig.portal_kullanici(id) ON DELETE CASCADE,
  bitis_utc    timestamptz NOT NULL
);
CREATE INDEX portal_kod_kullanici ON alig.portal_kod(kullanici_id);
CREATE INDEX portal_kod_bitis ON alig.portal_kod(bitis_utc);

CREATE TABLE alig.portal_oturum(
  kod_sha256     text PRIMARY KEY CHECK (kod_sha256 ~ '^[0-9a-f]{64}$'),
  kullanici_id   bigint NOT NULL REFERENCES alig.portal_kullanici(id) ON DELETE CASCADE,
  csrf           text NOT NULL,
  olusturma_utc  timestamptz NOT NULL,
  son_erisim_utc timestamptz NOT NULL
);
CREATE INDEX portal_oturum_kullanici ON alig.portal_oturum(kullanici_id);

CREATE TABLE alig.portal_deneme(
  id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  anahtar   text NOT NULL,
  zaman_utc timestamptz NOT NULL
);
CREATE INDEX portal_deneme_anahtar ON alig.portal_deneme(anahtar, zaman_utc);
CREATE INDEX portal_deneme_zaman ON alig.portal_deneme(zaman_utc);

-- Service request (audit, support, other) and account/data deletion request (silme). One open deletion request per company.
CREATE TABLE alig.portal_talep(
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  firma_id       bigint NOT NULL REFERENCES alig.firma(id) ON DELETE CASCADE,
  kullanici_id   bigint NOT NULL REFERENCES alig.portal_kullanici(id) ON DELETE CASCADE,
  tur            text NOT NULL CHECK (tur IN ('denetim', 'destek', 'diger', 'silme')),
  konu           text NOT NULL DEFAULT '',
  mesaj          text NOT NULL DEFAULT '',
  durum          text NOT NULL DEFAULT 'yeni' CHECK (durum IN ('yeni', 'inceleniyor', 'tamamlandi', 'reddedildi')),
  olusturma_utc  timestamptz NOT NULL,
  guncelleme_utc timestamptz NOT NULL
);
CREATE INDEX portal_talep_firma ON alig.portal_talep(firma_id, olusturma_utc);
CREATE INDEX portal_talep_kullanici ON alig.portal_talep(kullanici_id);
CREATE UNIQUE INDEX portal_talep_acik_silme ON alig.portal_talep(firma_id) WHERE tur = 'silme' AND durum IN ('yeni', 'inceleniyor');

RESET ROLE;
